// A narrower real donor Store makes the 431-byte canonical image require
// multiple actual chunks without increasing record or capture-size budgets.
fn reopen_polled_image_donor(group: &mut DynamicGroup) -> Result {
    drop(group.nodes[0].take());
    let local = &group.local[0];
    let name = format!("{}-{}", local.key().id, hex_bytes(&local.key().directory)?);
    let mut controller = protocol::Config::new(
        local.key().id,
        vec![local.key().id],
        "membership-test".into(),
    )?;
    controller.election_timeouts = Timeouts::new(DYNAMIC_ELECTION_MIN_MS, DYNAMIC_ELECTION_MAX_MS)?;
    let mut config = replication::Config::new(controller);
    config.quorum_timeout_ms = DYNAMIC_QUORUM_TIMEOUT_MS;
    let identity = snapshot::Identity::dynamic(
        "membership-test".into(),
        "__cluster_metadata".into(),
        0,
        group.genesis.clone(),
    )?;
    let defaults = snapshot::Limits::default();
    let limits = snapshot::Limits::new(
        defaults.image_bytes(),
        defaults.records(),
        defaults.payload_bytes(),
        defaults.record_bytes(),
        POLLED_IMAGE_CHUNK_BYTES,
        defaults.generations(),
        32,
    )?;
    let store = snapshot::Store::open(group.root.join(format!("{name}.images")), identity, limits)?;
    group.nodes[0] = Some(Node::open_dynamic(
        group.root.join(format!("{name}.wal")),
        group.root.join(format!("{name}.election")),
        config,
        Bootstrap::new(local.clone(), group.genesis.clone(), "CONTROLLER".into())?,
        Some(store),
        0,
    )?);
    Ok(())
}

fn polled_incoming_multichunk_fixture() -> Result<(
    DynamicGroup,
    replication::DynamicSnapshotRequest,
    Option<Key>,
)> {
    let mut group = DynamicGroup::new(3, voter(4)?)?;
    reopen_polled_image_donor(&mut group)?;
    group.elect(10)?;
    group.catch_up(1, 11)?;
    group.node(0)?.propose(b"committed image payload", 12)?;
    group.catch_up(1, 13)?;
    group.node(0)?.checkpoint([61; 16], 14)?;
    group.probe(3, 15)?;
    let key = group.key(3);
    let vote = group.node(3)?.voted_directory()?;
    let offer = group.node(0)?.prepare_dynamic_snapshot(key, 16)?;
    group.node(3)?.begin_dynamic_snapshot(offer, 16)?;
    Ok((group, offer, vote))
}

fn voting_incoming_image_fixture() -> Result<(
    DynamicGroup,
    replication::DynamicSnapshotRequest,
    Option<Key>,
)> {
    let mut group = DynamicGroup::new(3, voter(4)?)?;
    reopen_polled_image_donor(&mut group)?;
    group.elect(10)?;
    group.catch_up(1, 11)?;
    group.node(0)?.propose(b"committed image payload", 12)?;
    group.catch_up(1, 13)?;
    group.node(0)?.checkpoint([62; 16], 14)?;
    let key = group.key(2);
    let vote = group.node(2)?.voted_directory()?;
    assert_eq!(vote, Some(group.key(0)));
    let offer = group.node(0)?.prepare_dynamic_snapshot(key, 16)?;
    group.node(2)?.begin_dynamic_snapshot(offer, 16)?;
    Ok((group, offer, vote))
}

fn assert_no_partial_image(group: &DynamicGroup, receiver: usize) -> Result {
    let key = group.key(receiver);
    let images = group
        .root
        .join(format!("{}-{}.images", key.id, hex_bytes(&key.directory)?));
    for entry in fs::read_dir(images)? {
        assert!(!entry?.file_name().to_string_lossy().ends_with(".partial"));
    }
    Ok(())
}

